    """The Claude Code binary: ``KINTSUGI_CLAUDE_BIN`` if set, else ``claude`` on PATH."""
    return os.environ.get("KINTSUGI_CLAUDE_BIN") or "claude"


@dataclass(frozen=True)
class SessionRequest:
    prompt: str
    cwd: Path
    allowed_tools: tuple[str, ...]
    model: str = DEFAULT_MODEL
    session_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    max_budget_usd: float | None = None
    timeout_s: float = 2700.0  # the Surgeon activity's start_to_close (spec §5.3.2)
    settings: Mapping[str, Any] = field(default_factory=lambda: dict(DEFAULT_SETTINGS))
    extra_env: Mapping[str, str] = field(default_factory=dict)
    append_system_prompt: str | None = None
    resume: bool = False  # continue ``session_id`` (spike N7) instead of starting it


def build_argv(request: SessionRequest) -> list[str]:
    """The command line. The prompt itself is not on it: it is fed on stdin."""
    argv = [
        executable(), "-p",
        "--output-format", "stream-json", "--verbose",
        "--model", request.model,
        "--resume" if request.resume else "--session-id", request.session_id,
        "--allowedTools", ",".join(request.allowed_tools),
        "--strict-mcp-config",
        "--setting-sources", "project,local",  # no user plugins, skills or hooks in a Surgeon
        "--settings", json.dumps(dict(request.settings), separators=(",", ":")),
    ]  # fmt: skip
    if request.max_budget_usd is not None:
        argv += ["--max-budget-usd", f"{request.max_budget_usd:.2f}"]
    if request.append_system_prompt:
        argv += ["--append-system-prompt", request.append_system_prompt]
    return argv


@dataclass
class StreamSummary:
    session_id: str | None = None
    model: str | None = None
    api_key_source: str | None = None
    tool_uses: list[dict[str, Any]] = field(default_factory=list)
    result: dict[str, Any] | None = None
    error: str | None = None
    unparsed_lines: int = 0
    events: int = 0

    @property
    def cost_usd(self) -> float:
        return float((self.result or {}).get("total_cost_usd") or 0.0)

    @property
    def usage(self) -> dict[str, Any]:
        return dict((self.result or {}).get("usage") or {})

    @property
    def num_turns(self) -> int:
        return int((self.result or {}).get("num_turns") or 0)

    @property
    def is_error(self) -> bool:
        return self.error is not None or bool((self.result or {}).get("is_error"))

    def feed(self, event: Mapping[str, Any]) -> None:
        self.events += 1
        kind, subtype = event.get("type"), event.get("subtype")
        if kind == "system" and subtype == "init":
            self.session_id = event.get("session_id", self.session_id)
            self.model = event.get("model")
            self.api_key_source = event.get("apiKeySource")
        elif kind == "assistant":
            if event.get("error"):
                self.error = str(event["error"])
            content = (event.get("message") or {}).get("content") or []
            self.tool_uses += [
                {"name": block.get("name"), "input": block.get("input", {})}
                for block in content
                if isinstance(block, dict) and block.get("type") == "tool_use"
            ]
        elif kind == "result":
            self.result = dict(event)
            self.session_id = event.get("session_id", self.session_id)


def parse_stream(lines: Iterable[str]) -> StreamSummary:
    summary = StreamSummary()
    for line in lines:
        if not line.strip():
            continue
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            summary.unparsed_lines += 1
            continue
        if isinstance(event, dict):
            summary.feed(event)
    return summary


@dataclass(frozen=True)
class SessionResult:
    request: SessionRequest
    stream: StreamSummary
    exit_code: int | None
    timed_out: bool
    stopped_by_caller: bool
    transcript_path: Path | None
    transcript_sha256: str | None

    @property
    def session_id(self) -> str:
        return self.stream.session_id or self.request.session_id

    @property
    def ok(self) -> bool:
        return (
            self.exit_code == 0
            and not self.timed_out
            and not self.stopped_by_caller
            and not self.stream.is_error
        )


def find_transcript(session_id: str, claude_home: Path | None = None) -> Path | None:
    """Claude Code's native transcript: ``~/.claude/projects/<sanitised cwd>/<session>.jsonl``."""
    home = claude_home or Path.home() / ".claude"
    matches = sorted((home / "projects").glob(f"*/{session_id}.jsonl"))
    return matches[0] if matches else None


def file_sha256(path: Path) -> str:
    return "sha256:" + hashlib.sha256(path.read_bytes()).hexdigest()


def run(
    request: SessionRequest,
    *,
    on_event: Callable[[Mapping[str, Any]], bool] | None = None,
    claude_home: Path | None = None,
) -> SessionResult:
    """Run one session to completion. ``on_event`` returning True stops it (tree kill)."""
    stream = StreamSummary()
    timed_out = threading.Event()
    stopped = False
    with tempfile.TemporaryDirectory(prefix="kintsugi-session-") as scratch:
        prompt_file = Path(scratch) / "prompt.txt"
        prompt_file.write_bytes(request.prompt.encode("utf-8"))
        child = proc.start(
            build_argv(request),
            cwd=request.cwd,
            extra_env=request.extra_env,
            stderr_to=Path(scratch) / "stderr.log",
            stdin_path=prompt_file,
        )
        timer = threading.Timer(request.timeout_s, lambda: (timed_out.set(), child.kill_tree()))
        timer.start()
        try:
            for line in child.lines():
                if not line.strip():
                    continue
                try:
                    event = json.loads(line)
                except json.JSONDecodeError:
                    stream.unparsed_lines += 1
                    continue
                stream.feed(event)
                if on_event is not None and on_event(event):
                    stopped = True
                    child.kill_tree()
                    break
            exit_code = child.wait(timeout_s=60)
        finally:
            timer.cancel()
            child.kill_tree()
    session_id = stream.session_id or request.session_id
    transcript = find_transcript(session_id, claude_home)
    return SessionResult(
        request=request,
        stream=stream,
        exit_code=exit_code,
        timed_out=timed_out.is_set(),
        stopped_by_caller=stopped,
        transcript_path=transcript,
        transcript_sha256=file_sha256(transcript) if transcript else None,
    )


def auth_status() -> dict[str, Any]:
    result = proc.run([executable(), "auth", "status"], timeout_s=60)
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError:
        return {"loggedIn": False, "raw": result.stdout[-500:]}


def require_logged_in(extra_env: Mapping[str, str] | None = None) -> None:
    if extra_env and extra_env.get("ANTHROPIC_API_KEY"):
        return
    if not auth_status().get("loggedIn"):
        raise NotLoggedIn("the headless Claude Code CLI is not logged in: run `claude auth login`")

"""Orchestrator commits and the autonomy checks C2–C5 (spec §4.5, §7.5; plan §2a, §2b, §2d).

**Commit protocol** (:func:`orchestrator_commit`), run after a headless session exits:

1. stage everything in the worktree; refuse protected-path violations and an over-budget diff;
2. compute the tree SHA (``git write-tree``) and sign the attestation over it;
3. commit with the ``Kintsugi-*`` trailers under ``ENTIRE_TEST_TTY=0`` (the gateway forces it);
   Entire's ``prepare-commit-msg`` hook appends ``Entire-Checkpoint:``;
4. verify the commit kept the signed tree and parent, carries no forbidden trailer, and names a
   checkpoint whose ref exists. Otherwise the commit is undone (``reset --soft``) and refused,
   so an unlinked commit is never pushed.

**Checks** (:func:`verify_commit`), usable online or offline from the refs alone:

- C2 every ``Kintsugi-*`` trailer is present and no ``Co-authored-by:``/``Claude-Session:``;
- C3 the signature verifies over (nonce, tree, parent, role, incident, prompt hash);
- C4 the named checkpoint exists, its stored transcript is intact (``content_hash``), contains
  the nonce verbatim, and its ``files_touched`` covers the commit's changed files;
- C5 the first user prompt of the session hashes to ``Kintsugi-Prompt``.

``Kintsugi-Prompt`` is ``sha256`` of the exact UTF-8 bytes of the session's first prompt; the
attestation's ``prompt_template_sha`` field carries that same digest (Amendments log).
"""

from __future__ import annotations

import hashlib
import json
import re
from collections.abc import Iterable
from dataclasses import dataclass, field, replace
from pathlib import Path

from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

from kintsugi.gates.protected_paths import Policy
from kintsugi.memory import entire
from kintsugi.proof import attest
from kintsugi.sandbox import proc

FORBIDDEN_TRAILERS = ("Co-authored-by", "Claude-Session")
_FORBIDDEN = re.compile(r"^\s*(co-authored-by|claude-session)\s*:", re.IGNORECASE | re.MULTILINE)
_ULID = re.compile(r"^[0-9A-HJKMNP-TV-Z]{26}$")


class CommitRefused(RuntimeError):
    pass


class CheckpointMissing(CommitRefused):
    """The commit did not get a linked Entire checkpoint; it was undone."""


def prompt_digest(prompt: str) -> str:
    return "sha256:" + hashlib.sha256(prompt.encode("utf-8")).hexdigest()


def message_problems(
    message: str, *, require_attestation: bool, require_checkpoint: bool
) -> list[str]:
    problems: list[str] = []
    if _FORBIDDEN.search(message):
        problems.append(f"forbidden trailer present (one of {', '.join(FORBIDDEN_TRAILERS)})")
    trailers = attest.parse_trailers(message)
    if require_attestation:
        missing = [key for key in attest.TRAILER_KEYS if len(trailers.get(key, [])) != 1]
        if missing:
            problems.append(f"missing or repeated attestation trailers: {missing}")
    if require_checkpoint:
        ids = trailers.get(attest.ENTIRE_TRAILER, [])
        if len(ids) != 1 or not _ULID.match(ids[0]):
            problems.append(f"expected one valid {attest.ENTIRE_TRAILER} trailer, got {ids}")
    return problems


def _git(repo: Path, *args: str, input_text: str | None = None, timeout_s: float = 120.0) -> str:
    result = proc.run(["git", "-C", str(repo), *args], input_text=input_text, timeout_s=timeout_s)
    if not result.ok:
        detail = (result.stderr or result.stdout).strip()[-800:]
        raise CommitRefused(f"git {args[0]} failed: {detail}")
    return result.stdout


@dataclass(frozen=True)
class CommitOutcome:
    sha: str
    tree_sha: str
    parent_sha: str
    checkpoint_id: str | None
    attestation: attest.SessionAttestation
    changed_paths: tuple[str, ...]
    changed_lines: int


def _staged_paths(repo: Path) -> list[str]:
    return [p for p in _git(repo, "diff", "--cached", "--name-only", "-z").split("\0") if p]


def _staged_lines(repo: Path) -> int:
    total = 0
    for line in _git(repo, "diff", "--cached", "--numstat").splitlines():
        added, deleted, _ = line.split("\t", 2)
        total += (int(added) if added.isdigit() else 0) + (int(deleted) if deleted.isdigit() else 0)
    return total


def orchestrator_commit(
    worktree: Path,
    *,
    attestation: attest.SessionAttestation,
    signer: attest.Signer,
    subject: str,
    policy: Policy,
    scopes: Iterable[str] = ("surgeon",),
    body: str = "",
    approved_large_diff: bool = False,
    require_checkpoint: bool = True,
    session_paths: Iterable[str] | None = None,
    timeout_s: float = 120.0,
) -> CommitOutcome:
    """``session_paths``: files the session's Write/Edit tool calls touched (see
    :func:`tool_edited_paths`). Any other staged change is refused before committing, because
    Entire's checkpoint would not record it and audit check C4 would fail later."""
    worktree = Path(worktree)
    _git(worktree, "add", "-A")
    paths = _staged_paths(worktree)
    if not paths:
        raise CommitRefused("the session changed nothing")
    if session_paths is not None:
        unexplained = sorted(set(paths) - set(session_paths))
        if unexplained:
            _git(worktree, "reset", "-q")
            raise CommitRefused(f"changes the session's tool calls do not explain: {unexplained}")
    violations = policy.violations(paths, list(scopes))
    if violations:
        _git(worktree, "reset", "-q")
        raise CommitRefused(f"protected paths touched: {[(v.path, v.pattern) for v in violations]}")
    lines = _staged_lines(worktree)
    if policy.over_budget(lines) and not approved_large_diff:
        _git(worktree, "reset", "-q")
        budget = policy.diff_budget_lines
        raise CommitRefused(f"diff of {lines} lines exceeds the {budget}-line budget")
    tree = _git(worktree, "write-tree").strip()
    parent = _git(worktree, "rev-parse", "HEAD").strip()
    signed = attest.attest(attestation, signer, tree_sha=tree, parent_sha=parent)
    message = subject.strip() + "\n\n"
    message += (body.strip() + "\n\n") if body.strip() else ""
    message += attest.format_trailers(attest.trailers(signed)) + "\n"
    problems = message_problems(message, require_attestation=True, require_checkpoint=False)
    if problems:
        raise CommitRefused("; ".join(problems))
    _git(worktree, "commit", "-q", "-F", "-", input_text=message, timeout_s=timeout_s)
    sha = _git(worktree, "rev-parse", "HEAD").strip()
    final = _git(worktree, "log", "-1", "--format=%B", sha)
    problems = []
    if _git(worktree, "rev-parse", f"{sha}^{{tree}}").strip() != tree:
        problems.append("tree changed after signing")
    if _git(worktree, "rev-parse", f"{sha}^").strip() != parent:
        problems.append("parent changed after signing")
    problems += message_problems(
        final, require_attestation=True, require_checkpoint=require_checkpoint
    )
    checkpoint_id = (attest.parse_trailers(final).get(attest.ENTIRE_TRAILER) or [None])[0]
    if require_checkpoint and checkpoint_id and not _ref_exists(worktree, checkpoint_id):
        problems.append(f"checkpoint ref for {checkpoint_id} does not exist")
    if problems:
        _git(worktree, "reset", "-q", "--soft", parent)
        raise CheckpointMissing("; ".join(problems))
    return CommitOutcome(sha, tree, parent, checkpoint_id, signed, tuple(paths), lines)


def _ref_exists(repo: Path, checkpoint_id: str) -> bool:
    ref = entire.checkpoint_ref(checkpoint_id)
    result = proc.run(["git", "-C", str(repo), "show-ref", "--verify", "-q", ref], timeout_s=30)
    return result.returncode == 0


_EDIT_TOOLS = frozenset({"Write", "Edit", "MultiEdit", "NotebookEdit"})


def tool_edited_paths(tool_uses: Iterable[dict[str, object]], worktree: Path) -> set[str]:
    """Repository-relative POSIX paths a session's file-editing tool calls named."""
    root = Path(worktree).resolve()
    paths: set[str] = set()
    for use in tool_uses:
        if use.get("name") not in _EDIT_TOOLS:
            continue
        tool_input = use.get("input")
        raw = tool_input.get("file_path") if isinstance(tool_input, dict) else None
        if not isinstance(raw, str):
            continue
        candidate = Path(raw)
        absolute = candidate if candidate.is_absolute() else root / candidate
        try:
            paths.add(absolute.resolve().relative_to(root).as_posix())
        except ValueError:
            continue  # outside the worktree: never part of this commit
    return paths


# ---- C2–C5 ----------------------------------------------------------------------------------


def first_user_prompt(transcript: bytes) -> str | None:
    """The first real user prompt in a Claude Code native (``full.jsonl``) transcript."""
    for raw in transcript.splitlines():
        try:
            entry = json.loads(raw)
        except json.JSONDecodeError:
            continue
        if not isinstance(entry, dict) or entry.get("type") != "user" or entry.get("isMeta"):
            continue
        content = (entry.get("message") or {}).get("content")
        if isinstance(content, str):
            return content
        if isinstance(content, list):
            blocks = [b for b in content if isinstance(b, dict) and b.get("type") == "text"]
            texts = [str(b.get("text", "")) for b in blocks]
            if texts:
                return "".join(texts)
    return None


def check_c4(
    stored: entire.StoredCheckpoint, nonce: str, changed_paths: Iterable[str]
) -> list[str]:
    problems: list[str] = []
    if not stored.sessions:
        return ["checkpoint has no sessions"]
    if not all(session.intact for session in stored.sessions):
        problems.append("a stored transcript does not match its content_hash")
    if not any(nonce.encode("utf-8") in session.full for session in stored.sessions):
        problems.append("the attested nonce is not in any session transcript")
    untouched = sorted(set(changed_paths) - set(stored.files_touched))
    if untouched:
        problems.append(f"changed files the checkpoint does not record: {untouched}")
    return problems


def check_c5(stored: entire.StoredCheckpoint, expected_prompt_digest: str) -> list[str]:
    for session in stored.sessions:
        prompt = first_user_prompt(session.full)
        if prompt is not None and prompt_digest(prompt) == expected_prompt_digest:
            return []
    return ["no session's first prompt hashes to Kintsugi-Prompt"]


@dataclass(frozen=True)
class LinkageReport:
    commit: str
    checkpoint_id: str | None
    problems: dict[str, list[str]] = field(default_factory=dict)

    @property
    def ok(self) -> bool:
        return not any(self.problems.values())


def verify_commit(repo: Path, sha: str, *, public_key: Ed25519PublicKey) -> LinkageReport:
    """Checks C2–C5 for one commit, from git and the checkpoint refs alone."""
    repo = Path(repo)
    message = _git(repo, "log", "-1", "--format=%B", sha)
    trailers = attest.parse_trailers(message)
    problems: dict[str, list[str]] = {
        "C2": message_problems(message, require_attestation=True, require_checkpoint=True)
    }
    checkpoint_id = (trailers.get(attest.ENTIRE_TRAILER) or [None])[0]
    if problems["C2"]:
        return LinkageReport(sha, checkpoint_id, problems)
    one = {key: values[0] for key, values in trailers.items()}
    claimed = attest.SessionAttestation(
        nonce=one["Kintsugi-Nonce"], role=one["Kintsugi-Role"], incident=one["Kintsugi-Incident"],
        worktree="", base_sha="", prompt_template_sha=one["Kintsugi-Prompt"], t_start="",
        tree_sha=_git(repo, "rev-parse", f"{sha}^{{tree}}").strip(),
        parent_sha=_git(repo, "rev-parse", f"{sha}^").strip(),
        signature=one["Kintsugi-Attestation"],
    )  # fmt: skip
    problems["C3"] = [] if attest.verify_attestation(claimed, public_key) else ["bad signature"]
    try:
        stored = entire.read_checkpoint(repo, str(checkpoint_id))
    except entire.EntireError as error:
        problems["C4"] = [str(error)]
        problems["C5"] = ["no checkpoint to read the prompt from"]
        return LinkageReport(sha, checkpoint_id, problems)
    changed = [p for p in _git(repo, "diff-tree", "--no-commit-id", "--name-only", "-r", "-z", sha)
               .split("\0") if p]  # fmt: skip
    problems["C4"] = check_c4(stored, claimed.nonce, changed)
    problems["C5"] = check_c5(stored, claimed.prompt_template_sha)
    return LinkageReport(sha, checkpoint_id, problems)


def why_agrees(repo: Path, sha: str, checkpoint_id: str, *, samples: int = 3) -> list[str]:
    """Cross-check with ``entire why``: sampled added lines resolve to this commit and its
    checkpoint."""
    problems: list[str] = []
    diff = _git(Path(repo), "show", "--format=", "--unified=0", sha)
    targets: list[tuple[str, int]] = []
    path = None
    for line in diff.splitlines():
        if line.startswith("+++ b/"):
            path = line[6:]
        elif line.startswith("@@") and path is not None:
            match = re.search(r"\+(\d+)", line)
            if match:
                targets.append((path, int(match.group(1))))
    for path_, number in targets[:samples]:
        found = entire.why(repo, path_, number)
        if found.checkpoint_id != checkpoint_id or not found.commit_sha.startswith(sha[:7]):
            problems.append(f"{path_}:{number} → {found.checkpoint_id} @ {found.commit_sha[:8]}")
    return problems


def strip_nonce(stored: entire.StoredCheckpoint, nonce: str) -> entire.StoredCheckpoint:
    """A mutated copy without the nonce (keeps content_hash): the negative control for C4."""
    sessions = [replace(s, full=s.full.replace(nonce.encode(), b"")) for s in stored.sessions]
    return replace(stored, sessions=sessions)

"""Session attestation and commit trailers (spec §4.5, Appendix E.6).

The orchestrator signs ``sha256(nonce ‖ tree_sha ‖ parent_sha ‖ role ‖ incident ‖
prompt_template_sha)`` for every commit an agent session produces. The concatenation ``‖`` is
realised as the RFC 8785 encoding of the six fields as a JSON array, so field boundaries are
unambiguous.

Keys: local Ed25519 now; an AWS KMS ``ECC_NIST_P256`` signer can implement :class:`Signer` in
Stage 8. The private key never enters the repository or any agent's context: the T0 key is
generated under the Architect's custody (``kintsugi keys generate``) and only the OpenSSH public
key is committed to ``.kintsugi/attest.pub``.

Commit identity (ruling D4): every commit is authored and committed by the Architect's git
identity; machine origin is proven by these trailers, never by a bot account or a
``Co-authored-by:`` trailer, which :func:`commit_message_problems` rejects.
"""

from __future__ import annotations

import base64
import hashlib
import os
import re
from dataclasses import dataclass, replace
from pathlib import Path
from typing import Protocol

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey

from kintsugi.proof.canonical import canonicalize
from kintsugi.proof.passphrase import is_nonce

TRAILER_KEYS = (
    "Kintsugi-Incident",
    "Kintsugi-Role",
    "Kintsugi-Nonce",
    "Kintsugi-Prompt",
    "Kintsugi-Attestation",
)
ENTIRE_TRAILER = "Entire-Checkpoint"
_TRAILER_LINE = re.compile(r"^([A-Za-z0-9][A-Za-z0-9-]*):\s?(.*)$")
_COAUTHOR = re.compile(r"^\s*co-authored-by\s*:", re.IGNORECASE | re.MULTILINE)


class Signer(Protocol):
    algorithm: str

    def sign(self, digest: bytes) -> bytes: ...

    def public_key_openssh(self) -> str: ...


class Ed25519Signer:
    algorithm = "ed25519"

    def __init__(self, key: Ed25519PrivateKey) -> None:
        self._key = key

    @classmethod
    def generate(cls) -> Ed25519Signer:
        return cls(Ed25519PrivateKey.generate())

    @classmethod
    def load(cls, private_key_path: str | os.PathLike[str]) -> Ed25519Signer:
        key = serialization.load_ssh_private_key(Path(private_key_path).read_bytes(), None)
        if not isinstance(key, Ed25519PrivateKey):
            raise TypeError("the attestation key must be Ed25519")
        return cls(key)

    def sign(self, digest: bytes) -> bytes:
        return self._key.sign(digest)

    def public_key_raw(self) -> bytes:
        return self._key.public_key().public_bytes(
            serialization.Encoding.Raw, serialization.PublicFormat.Raw
        )

    def public_key_openssh(self, comment: str = "kintsugi-omega-attest") -> str:
        key = self._key.public_key().public_bytes(
            serialization.Encoding.OpenSSH, serialization.PublicFormat.OpenSSH
        )
        return f"{key.decode('ascii')} {comment}"

    def save(
        self, private_key_path: str | os.PathLike[str], public_key_path: str | os.PathLike[str]
    ) -> None:
        private_path = Path(private_key_path)
        if private_path.exists():
            raise FileExistsError(f"refusing to overwrite an existing key: {private_path}")
        private_path.parent.mkdir(parents=True, exist_ok=True)
        pem = self._key.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.OpenSSH,
            serialization.NoEncryption(),
        )
        descriptor = os.open(private_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(pem)
        public_path = Path(public_key_path)
        public_path.parent.mkdir(parents=True, exist_ok=True)
        public_path.write_text(self.public_key_openssh() + "\n", encoding="ascii", newline="\n")


def load_public_key(text_or_path: str | os.PathLike[str]) -> Ed25519PublicKey:
    """Load an OpenSSH Ed25519 public key from its text or from a file such as attest.pub."""
    raw = os.fspath(text_or_path)
    text = raw if raw.startswith("ssh-ed25519 ") else Path(raw).read_text(encoding="ascii")
    key = serialization.load_ssh_public_key(text.strip().encode("ascii"))
    if not isinstance(key, Ed25519PublicKey):
        raise TypeError("the attestation key must be Ed25519")
    return key


def fingerprint(public_key: Ed25519PublicKey) -> str:
    raw = public_key.public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)
    return "SHA256:" + base64.b64encode(hashlib.sha256(raw).digest()).decode().rstrip("=")


@dataclass(frozen=True)
class SessionAttestation:
    """Appendix E.6. ``tree_sha``, ``parent_sha`` and ``signature`` are filled at commit time."""

    nonce: str
    role: str
    incident: str
    worktree: str
    base_sha: str
    prompt_template_sha: str
    t_start: str
    hypothesis: str | None = None
    tree_sha: str | None = None
    parent_sha: str | None = None
    signature: str | None = None

    @property
    def role_label(self) -> str:
        return f"{self.role}/{self.hypothesis}" if self.hypothesis else self.role


def signing_digest(
    nonce: str,
    tree_sha: str,
    parent_sha: str,
    role: str,
    incident: str,
    prompt_template_sha: str,
) -> bytes:
    fields = [nonce, tree_sha, parent_sha, role, incident, prompt_template_sha]
    return hashlib.sha256(canonicalize(fields)).digest()


def _digest_for(att: SessionAttestation) -> bytes:
    if att.tree_sha is None or att.parent_sha is None:
        raise ValueError("tree_sha and parent_sha are required to sign or verify")
    return signing_digest(
        att.nonce, att.tree_sha, att.parent_sha, att.role_label, att.incident,
        att.prompt_template_sha,
    )  # fmt: skip


def attest(
    att: SessionAttestation, signer: Signer, *, tree_sha: str, parent_sha: str
) -> SessionAttestation:
    if not is_nonce(att.nonce):
        raise ValueError("the nonce must be a 128-bit passphrase (spike N1)")
    filled = replace(att, tree_sha=tree_sha, parent_sha=parent_sha)
    signature = base64.b64encode(signer.sign(_digest_for(filled))).decode("ascii")
    return replace(filled, signature=f"{signer.algorithm}:{signature}")


def verify_attestation(att: SessionAttestation, public_key: Ed25519PublicKey) -> bool:
    if att.signature is None or not att.signature.startswith("ed25519:"):
        return False
    try:
        signature = base64.b64decode(att.signature.removeprefix("ed25519:"), validate=True)
        public_key.verify(signature, _digest_for(att))
    except (InvalidSignature, ValueError):
        return False
    return True


def trailers(att: SessionAttestation) -> list[tuple[str, str]]:
    if att.signature is None:
        raise ValueError("sign the attestation before writing trailers")
    values = [att.incident, att.role_label, att.nonce, att.prompt_template_sha, att.signature]
    return list(zip(TRAILER_KEYS, values, strict=True))


def format_trailers(pairs: list[tuple[str, str]]) -> str:
    return "\n".join(f"{key}: {value}" for key, value in pairs)


def parse_trailers(message: str) -> dict[str, list[str]]:
    """Trailers from the trailing trailer-only paragraphs of a commit message.

    Consecutive trailing paragraphs that consist only of ``Key: value`` lines are merged, so the
    orchestrator's ``Kintsugi-*`` block and an ``Entire-Checkpoint:`` line that a hook appends
    in its own paragraph are read together. The subject line is never a trailer.
    """
    paragraphs = [block for block in re.split(r"\n\s*\n", message.strip()) if block.strip()]
    parsed: dict[str, list[str]] = {}
    for block in reversed(paragraphs[1:]):
        matches = [_TRAILER_LINE.match(line.strip()) for line in block.splitlines()]
        if not all(matches):
            break  # prose: the trailer section ends here
        for match in reversed(matches):
            assert match is not None
            parsed.setdefault(match.group(1), []).insert(0, match.group(2).strip())
    return parsed


def commit_message_problems(message: str, *, require_attestation: bool) -> list[str]:
    """Policy check run before every commit the orchestrator makes."""
    problems: list[str] = []
    if _COAUTHOR.search(message):
        problems.append("Co-authored-by trailers are forbidden (ruling D4)")
    if require_attestation:
        found = parse_trailers(message)
        missing = [key for key in TRAILER_KEYS if key not in found]
        if missing:
            problems.append(f"missing attestation trailers: {missing}")
    return problems

