    summary = StreamSummary()
    for line in lines:
        if not line.strip():
            continue
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            summary.unparsed_lines += 1
            continue
        if isinstance(event, dict):
            summary.feed(event)
