        child = proc.start(
            build_argv(request),
            cwd=request.cwd,
            extra_env=request.extra_env,
            stderr_to=Path(scratch) / "stderr.log",
            stdin_path=prompt_file,
        )
        timer = threading.Timer(request.timeout_s, lambda: (timed_out.set(), child.kill_tree()))
        timer.start()
        try:
            for line in child.lines():
