        request=request,
        stream=stream,
        exit_code=exit_code,
        timed_out=timed_out.is_set(),
        stopped_by_caller=stopped,
        transcript_path=transcript,
        transcript_sha256=file_sha256(transcript) if transcript else None,
    )


