    "signature": "summary",
    "symptom": "summary",
    "repro": "summary",
    "graph_context": "source",
    "cause": "intent",
    "intent_record": "intent",
    "plan": "budget",
    "card": "cards",
    "outcome": "diffs",
    "refusal": "diffs",
    "surgeon_report": "reasoning",
    "surgeon_session": "reasoning",
    "verdict": "verdicts",
    "decision": "verdicts",
    "experiment": "verdicts",
    "reverify": "verdicts",
    "feedback": "feedback",
    "prior": "prior",
}

# Spec §5.7 information-flow matrix (rows: roles; values: readable artifact classes). The
# governor and the shipper are deterministic orchestrator code with their own narrow rows.
READS: Mapping[str, frozenset[str]] = {
    "sentinel": frozenset({"hits"}),
    "pathologist": frozenset({"hits", "traces", "summary"}),
    "archivist": frozenset({"summary", "source", "intent", "prior"}),
    "coordinator": frozenset({"summary", "intent", "budget", "cards", "verdicts", "feedback",
                              "prior"}),  # fmt: skip
    "surgeon": frozenset({"summary", "intent", "cards", "feedback"}),
    "auditor": frozenset({"traces", "summary", "source", "intent", "cards", "diffs",
                          "verdicts"}),  # fmt: skip
    "governor": frozenset({"budget", "summary"}),
    "shipper": frozenset({"summary", "intent", "budget", "cards", "diffs", "verdicts"}),
}

