    # ---- role views --------------------------------------------------------------------------

    def reader(self, role: str) -> CaseView:
        if role not in READS:
            raise KeyError(f"unknown role {role!r}")
        return CaseView(self, role)

    # ---- append-only logs ----------------------------------------------------------------------

    def _append(self, log: str, record: Mapping[str, Any]) -> None:
